#!/usr/bin/env bash
# DROIT À L'IMAGE — incrément 2 (front) :
#   - création de compte : majorité obligatoire ; mineur → date de naissance + parent référent ;
#   - fiche admin : majorité et parent référent, formulaire pré-rempli ; voie de chaque version ;
#   - liste des membres : colonne « Majorité » ;
#   - profil : autorisation en ligne des majeurs (mot de passe), message des mineurs, formulaire pré-rempli.
# Prérequis : apply-droit-image-backend.sh.
# Usage (racine du repo) : bash apply-droit-image-front.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/image-consent/OnlineConsentForm.tsx" 2>/dev/null | grep -qF "export function OnlineConsentForm"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export async function confirmMemberConsent" "packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-droit-image-backend.sh"; exit 1; }
MODIFIED=("apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/app/(admin)/dashboard/users/create/page.tsx" "apps/web/src/features/admin/users/components/ImageConsentForms.tsx" "apps/web/src/features/admin/users/components/UsersTable.tsx" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" "apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" "apps/web/src/features/image-consent/MyImageConsent.tsx" "packages/backend/src/modules/imageConsent/imageConsentForm.service.ts" "packages/backend/src/modules/users/router.ts" "packages/contracts/src/legal/imageConsent.ts")
CREATED=("apps/web/src/features/admin/users/legal/LegalInfoControl.tsx" "apps/web/src/features/admin/users/legal/LegalInfoFields.tsx" "apps/web/src/features/image-consent/OnlineConsentForm.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/features/admin/users/legal" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "export function OnlineConsentForm" "apps/web/src/features/image-consent/OnlineConsentForm.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/users/legal"
base64 -d > "apps/web/src/features/admin/users/legal/LegalInfoControl.tsx" <<'B64'
